# Verify that the generated MSI places the app's shortcut in the Start menu.
# Directory IDs may be generated by WiX, so resolve ancestry in the MSI Directory table.
$ErrorActionPreference = "Stop"
$msiFiles = @(Get-ChildItem "app-desktop/build/compose/binaries/main/msi/*.msi" -File)
if ($msiFiles.Count -ne 1) {
    throw "Expected exactly one MSI installer; found $($msiFiles.Count)."
}

$installer = New-Object -ComObject WindowsInstaller.Installer
$database = $installer.OpenDatabase($msiFiles[0].FullName, 0)

$directories = @{}
$directoryView = $database.OpenView("SELECT Directory, Directory_Parent, DefaultDir FROM Directory")
try {
    $directoryView.Execute()
    while ($record = $directoryView.Fetch()) {
        $directories[$record.StringData(1)] = @{
            Parent = $record.StringData(2)
            Name = $record.StringData(3)
        }
    }
}
finally {
    $directoryView.Close()
}

$shortcutView = $database.OpenView("SELECT Directory_, Name FROM Shortcut")
try {
    $shortcutView.Execute()
    $found = $false
    while ($record = $shortcutView.Fetch()) {
        $directory = $record.StringData(1)
        $shortcut = $record.StringData(2)
        $chain = [System.Collections.Generic.List[string]]::new()
        $seen = [System.Collections.Generic.HashSet[string]]::new()
        $current = $directory
        $startMenuAncestor = $false
        $inAppGroup = $false

        while ($current -and $seen.Add($current)) {
            $chain.Add($current)
            if ($current -match 'ProgramMenu') {
                $startMenuAncestor = $true
            }
            if (-not $directories.ContainsKey($current)) {
                break
            }
            $entry = $directories[$current]
            # MSI DefaultDir may contain a short|long filename representation.
            $longName = ($entry.Name -split '\|')[-1]
            $chain.Add($longName)
            if ($longName -eq "GRBL Commander") {
                $inAppGroup = $true
            }
            $current = $entry.Parent
        }

        Write-Host "MSI shortcut '$shortcut' -> $($chain -join ' / ')"
        if ($startMenuAncestor -and $inAppGroup) {
            $found = $true
        }
    }

    if (-not $found) {
        throw "MSI does not contain a shortcut in the GRBL Commander Start menu group."
    }
    Write-Host "Verified: MSI shortcut is under the GRBL Commander Start menu group."
}
finally {
    $shortcutView.Close()
}
